package com.studenthub.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.studenthub.dao.PrivateMessageDAO;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet(name="PollPrivateMessagesServlet",urlPatterns="/messages/poll")
public class PollPrivateMessagesServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();private final ObjectMapper json=new ObjectMapper();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{long c=Long.parseLong(q.getParameter("conversationId")),after=Long.parseLong(Optional.ofNullable(q.getParameter("afterMessageId")).orElse("0")),me=(Long)q.getSession().getAttribute("userId");var rows=dao.messages(c,me,after);dao.markDelivered(c,me);r.setContentType("application/json");r.setCharacterEncoding("UTF-8");json.writeValue(r.getWriter(),Map.of("messages",rows.stream().map(m->Map.of("messageId",m.messageId(),"senderId",m.senderId(),"message",m.message()==null?"":m.message(),"createdLabel",m.getCreatedLabel(),"status",m.getStatus())).toList(),"receipts",dao.receipts(c,me)));}catch(SecurityException e){r.sendError(403);}catch(Exception e){r.sendError(400);}}}
